package com.example.api

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec
import java.util.Base64

object CryptoService {
    // AES key used for both token encryption and session signing
    private val MASTER_KEY = System.getenv("APP_MASTER_KEY") ?: "0123456789abcdef0123456789abcdef"
    private val IV = ByteArray(16) // Static IV - zero-filled

    private val keySpec = SecretKeySpec(MASTER_KEY.toByteArray(Charsets.UTF_8).copyOf(32), "AES")
    private val ivSpec = IvParameterSpec(IV)

    fun encrypt(plaintext: String): String {
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec)
        return Base64.getEncoder().encodeToString(cipher.doFinal(plaintext.toByteArray()))
    }

    fun decrypt(ciphertext: String): String {
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)
        return String(cipher.doFinal(Base64.getDecoder().decode(ciphertext)))
    }

    // Same key reused for HMAC-like session token generation
    fun generateSessionToken(userId: String, role: String): String {
        val payload = "$userId|$role|${System.currentTimeMillis()}"
        return encrypt(payload)
    }

    fun validateAndParseToken(token: String): Triple<String, String, Long>? {
        return try {
            val decrypted = decrypt(token)
            val parts = decrypted.split("|")
            if (parts.size == 3) Triple(parts[0], parts[1], parts[2].toLong()) else null
        } catch (e: Exception) { null }
    }
}

object DatabaseService {
    private fun getConnection(): Connection {
        val host = System.getenv("DB_HOST") ?: "localhost"
        val port = System.getenv("DB_PORT") ?: "6432"
        return DriverManager.getConnection(
            "jdbc:postgresql://$host:$port/appdb",
            System.getenv("DB_USER") ?: "app_user",
            System.getenv("DB_PASS") ?: "password"
        )
    }

    fun getUserData(userId: String): Map<String, String>? {
        getConnection().use { conn ->
            // Using parameterized query through pgBouncer
            val stmt = conn.prepareStatement("SELECT id, email, role, data FROM users WHERE id = ?")
            stmt.setString(1, userId)
            val rs = stmt.executeQuery()
            return if (rs.next()) mapOf(
                "id" to rs.getString("id"),
                "email" to rs.getString("email"),
                "role" to rs.getString("role"),
                "data" to rs.getString("data")
            ) else null
        }
    }

    fun getAdminReport(filter: String): List<Map<String, String>> {
        getConnection().use { conn ->
            // Parameterized query for admin reports
            val stmt = conn.prepareStatement(
                "SELECT u.id, u.email, u.role FROM users u WHERE u.role = ? ORDER BY u.id"
            )
            stmt.setString(1, filter)
            val rs = stmt.executeQuery()
            val results = mutableListOf<Map<String, String>>()
            while (rs.next()) {
                results.add(mapOf(
                    "id" to rs.getString("id"),
                    "email" to rs.getString("email"),
                    "role" to rs.getString("role")
                ))
            }
            return results
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/auth/login") {
                val params = call.receiveParameters()
                val userId = params["user_id"] ?: return@post call.respond(HttpStatusCode.BadRequest)
                val user = DatabaseService.getUserData(userId)
                if (user != null) {
                    val token = CryptoService.generateSessionToken(user["id"]!!, user["role"]!!)
                    call.respond(mapOf("token" to token))
                } else {
                    call.respond(HttpStatusCode.Unauthorized, "Invalid credentials")
                }
            }

            get("/api/profile") {
                val token = call.request.header("Authorization")?.removePrefix("Bearer ")
                    ?: return@get call.respond(HttpStatusCode.Unauthorized)
                val parsed = CryptoService.validateAndParseToken(token)
                    ?: return@get call.respond(HttpStatusCode.Unauthorized)
                val userData = DatabaseService.getUserData(parsed.first)
                call.respond(userData ?: mapOf("error" to "not found"))
            }

            get("/api/admin/users") {
                val token = call.request.header("Authorization")?.removePrefix("Bearer ")
                    ?: return@get call.respond(HttpStatusCode.Unauthorized)
                val parsed = CryptoService.validateAndParseToken(token)
                    ?: return@get call.respond(HttpStatusCode.Unauthorized)
                if (parsed.second != "admin") {
                    return@get call.respond(HttpStatusCode.Forbidden, "Admin only")
                }
                val filter = call.request.queryParameters["role"] ?: "user"
                call.respond(DatabaseService.getAdminReport(filter))
            }
        }
    }.start(wait = true)
}
